"""What a module generated by the Python backend needs at run time (shipped, next to the
modules, as `j2jme_runtime.py`, followed by the built-in functions of `compiler/builtins.py`).

It imports nothing of the engine: the host project runs the generated modules with its own
interpreter. The rules it keeps are the engine's, not Python's:

- a path through the input (`root.a.b[0].c`) yields null where anything on the way is missing,
  never an error;
- arithmetic on a null is null; an ordering comparison with a null is false (as in SQL);
- a rule that fails leaves its field out and is reported once, under its name; the others go on;
- an empty text is null, as in Oracle: it is read as null from the input, built-ins give null for it,
  and the output never holds one;
- a bare `return` leaves the field out, `return Null` (or a value that is null) puts a null.
"""

from __future__ import annotations

import atexit
import contextvars
import importlib.util
import itertools
import json
import operator
import os
from concurrent.futures import ProcessPoolExecutor, ThreadPoolExecutor
from typing import Any


class _Omit:
    """What a rule gives when it contributes nothing: the field is left out."""

    def __repr__(self) -> str:
        return "OMIT"

    def __bool__(self) -> bool:
        return False


OMIT = _Omit()

_errors: contextvars.ContextVar[dict[str, str] | None] = contextvars.ContextVar(
    "j2jme_errors", default=None
)


class MappingError(Exception):
    """The mapping ran, but rules failed: `errors` is `[{"rule", "cause"}, ...]`."""

    def __init__(self, mapping_id: str, errors: list[dict[str, str]]):
        self.mapping_id = mapping_id
        self.errors = errors
        super().__init__(
            json.dumps({"mapping": mapping_id, "total_errors": len(errors), "errors": errors})
        )


class MissingImplementation(Exception):
    """A function the project declares has no code for Python: the rule that calls it did not run."""


def _rule(name: str, function: Any, *args: Any) -> Any:
    """Calls a rule function; a failure is recorded (the first one of the rule) and the rule
    gives OMIT."""
    try:
        return function(*args)
    except Exception as exc:  # noqa: BLE001 - any failure of a rule is that rule's
        errors = _errors.get()
        if errors is not None and name not in errors:
            errors[name] = f"{type(exc).__name__}: {exc}"
        return OMIT


_pools: dict[tuple[int, str], ProcessPoolExecutor] = {}
_worker_modules: dict[str, Any] = {}


def _shutdown_pools() -> None:
    for pool in _pools.values():
        pool.shutdown(wait=False, cancel_futures=True)
    _pools.clear()


atexit.register(_shutdown_pools)


def _process_pool(degree: int) -> ProcessPoolExecutor:
    """The worker processes of this degree, started once and kept: a worker puts the folder of this
    runtime on its path (the modules are loaded by path, they are not on the host's)."""
    folder = os.path.dirname(os.path.abspath(__file__))
    pool = _pools.get((degree, folder))
    if pool is None:
        pool = ProcessPoolExecutor(
            max_workers=degree,
            initializer=exec,
            initargs=(f"import sys; sys.path.insert(0, {folder!r})",),
        )
        _pools[(degree, folder)] = pool
    return pool


def _call_in_worker(
    file: str, function: str, name: str, args: tuple
) -> tuple[Any, dict[str, str], bool]:
    """Runs in a worker process: calls the rule `function` of the module `file` on `args`. Gives
    what it gave (null for OMIT, which is flagged: the marker does not survive the trip), and the
    errors of the call."""
    module = _worker_modules.get(file)
    if module is None:
        spec = importlib.util.spec_from_file_location(f"_j2jme_worker_{len(_worker_modules)}", file)
        assert spec is not None and spec.loader is not None
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        _worker_modules[file] = module
    errors: dict[str, str] = {}
    token = _errors.set(errors)
    try:
        value = _rule(name, getattr(module, function), *args)
    finally:
        _errors.reset(token)
    return (None, errors, True) if value is OMIT else (value, errors, False)


def _in_processes(
    name: str, function: Any, degree: int, calls: list[tuple]
) -> list[tuple[Any, dict[str, str]]] | None:
    """The calls run in worker processes, in element order; None when they cannot (the rule is not
    in a module that has a file, an argument or a result cannot travel, the workers died): the
    caller then runs them itself, with the same result."""
    file = getattr(function, "__globals__", {}).get("__file__")
    if not file:
        return None
    pool = _process_pool(degree)
    # (no `max` here: the built-ins of the language, which shadow Python's, follow this text)
    chunk = len(calls) // (degree * 4) or 1
    try:
        got = list(
            pool.map(
                _call_in_worker,
                itertools.repeat(file),
                itertools.repeat(function.__name__),
                itertools.repeat(name),
                calls,
                chunksize=chunk,
            )
        )
    except Exception:  # noqa: BLE001 - a pickling failure or a broken pool: not the rule's error
        _pools.clear()
        pool.shutdown(wait=False, cancel_futures=True)
        return None
    return [(OMIT if omitted else value, errors) for value, errors, omitted in got]


def _pmap(
    target: list[Any],
    name: str,
    function: Any,
    degree: int,
    calls: list[tuple],
    mode: str = "thread",
) -> None:
    """What a loop does with a `@parallel` element rule: the rule is called for each element in up
    to `degree` threads (or processes, `mode`), and what it gives is appended to `target` in element
    order. Each call keeps its own errors, merged in element order afterwards, so the first failure
    of a rule is the first element's and the result is the sequential one's, whatever the timing."""

    def one(args: tuple) -> tuple[Any, dict[str, str]]:
        errors: dict[str, str] = {}
        token = _errors.set(errors)
        try:
            return _rule(name, function, *args), errors
        finally:
            _errors.reset(token)

    results = None
    if degree > 1 and len(calls) > 1:
        if mode == "process":
            results = _in_processes(name, function, degree, calls)
        if results is None and mode != "none":
            with ThreadPoolExecutor(max_workers=degree) as pool:
                results = list(pool.map(one, calls))
    if results is None:
        results = [one(args) for args in calls]
    outer = _errors.get()
    for value, errors in results:
        _append(target, value)
        if outer is not None:
            for rule, cause in errors.items():
                outer.setdefault(rule, cause)


def _get(value: Any, *path: Any) -> Any:
    """`value` followed along `path` (names and positions); null as soon as a step is missing."""
    for step in path:
        if value is None:
            return None
        if isinstance(step, int):
            if isinstance(value, list) and -len(value) <= step < len(value):
                value = value[step]
            else:
                return None
        else:
            value = value.get(step) if isinstance(value, dict) else None
    return value


def _each(value: Any) -> Any:
    """What a `for` runs over: the elements of an array; nothing for a missing one."""
    if value is None:
        return []
    if isinstance(value, list):
        return value
    raise TypeError(f"cannot iterate over {type(value).__name__}")


def _record(**fields: Any) -> dict[str, Any]:
    """An object of the output: the fields that were left out are not in it."""
    return {k: v for k, v in fields.items() if v is not OMIT}


def _append(target: list[Any], value: Any) -> None:
    if value is not OMIT:
        target.append(value)


class _Out:
    """The output being built: `out.F = v` sets a field (not when v is OMIT), and reading a name
    that is not set yet gives the array to append to."""

    def __init__(self) -> None:
        object.__setattr__(self, "_fields", {})

    def __setattr__(self, name: str, value: Any) -> None:
        if value is not OMIT:
            self._fields[name] = value

    def __getattr__(self, name: str) -> Any:
        return self._fields.setdefault(name, [])


def _arith(op: Any):
    def apply(a: Any, b: Any) -> Any:
        return None if a is None or b is None else op(a, b)

    return apply


_add = _arith(operator.add)
_sub = _arith(operator.sub)
_mul = _arith(operator.mul)
_div = _arith(operator.truediv)
_floordiv = _arith(operator.floordiv)
_mod = _arith(operator.mod)


def _neg(a: Any) -> Any:
    return None if a is None else -a


def _order(op: Any):
    def compare(a: Any, b: Any) -> bool:
        return False if a is None or b is None else op(a, b)

    return compare


_lt = _order(operator.lt)
_le = _order(operator.le)
_gt = _order(operator.gt)
_ge = _order(operator.ge)


def _blank(value: Any) -> Any:
    """`value` with every empty text replaced by null (an empty text is null, as in Oracle)."""
    if value == "":
        return None
    if isinstance(value, dict):
        return {k: _blank(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_blank(v) for v in value]
    return value


def _plain(value: Any) -> Any:
    """The output as JSON: a number that is whole is written as an integer (5, not 5.0), an empty
    text is null."""
    if value == "":
        return None
    if isinstance(value, float) and value.is_integer():
        return int(value)
    if isinstance(value, dict):
        return {k: _plain(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_plain(v) for v in value]
    return value


def _execute(
    mapping_id: str, run: Any, source: Any, raising: bool
) -> tuple[Any, list[dict[str, str]]]:
    """Runs a mapping on `source` (JSON text, or the parsed document). Gives the output and
    the rule errors; with `raising`, a MappingError instead when there are errors."""
    document = json.loads(source) if isinstance(source, str | bytes | bytearray) else source
    document = _blank(document)
    errors: dict[str, str] = {}
    token = _errors.set(errors)
    out = _Out()
    try:
        run(document, out)
    except Exception as exc:  # noqa: BLE001 - outside any rule: reported as the mapping's own
        errors.setdefault("<mapping>", f"{type(exc).__name__}: {exc}")
    finally:
        _errors.reset(token)
    report = [{"rule": rule, "cause": cause} for rule, cause in errors.items()]
    if raising and report:
        raise MappingError(mapping_id, report)
    return _plain(out._fields), report
